using System.Numerics;

namespace SmSim.Extras.Musou.Ashfall;

/// <summary>
/// Late batch F (2026-11-06; ours): finds the stairs of a kit model in its own mesh, for the stair ramps of the level (<see cref="AshfallKitCollision.Stairs"/>, generated by <c>smtool ashfall-kit-stairs</c>).
/// The draft-5 ramps (<see cref="AshfallKitFit"/>'s <c>FindRamps</c>) were read from the fitted voxel grid: they took a stair's sloped side cheeks and the stepped tops of broken walls for stairs, missed treads the box cap had merged
/// and judged the slope in the raw frame before the placement's scale. Here: the mesh's top surface on a fine grid (<see cref="Resolution"/> cells on the longer horizontal axis, every triangle rasterised, the highest
/// surface kept), read along each row and column as plateaus (cells within <see cref="FlatCells"/> of a cell's size in height); a stair is a chain of at least <see cref="MinRises"/> rises from a floor through treads
/// (each at least <see cref="MinTreadCells"/> cells deep, no riser more than twice another) to a landing; a smooth slope (a cheek, a rubble ramp) has no treads and is not a stair. Equal chains on at least
/// <see cref="MinLines"/> neighbouring lines make one stair. The result, in the raw glTF frame, is an <see cref="AshfallRamp"/>: the footprint from the first riser to the last, the floor's height at the foot
/// (<see cref="AshfallRamp.YLow"/>) and the landing's (<see cref="AshfallRamp.YHigh"/>): its plane runs over the step nosings.
/// </summary>
public static class AshfallStairDetect
{
    /// <summary>Grid cells on the longer horizontal axis (ours: a tread of a fifth of a 1.6-unit platform's stair is 3 cells).</summary>
    public const int Resolution = 128;

    /// <summary>Height changes up to this share of a cell are flat (bevels, noise).</summary>
    public const float FlatCells = 0.35f;

    /// <summary>Fewest rises (a stair of three steps or more), fewest cells a tread spans, fewest neighbouring lines (the stair's width).</summary>
    public const int MinRises = 3, MinTreadCells = 2, MinLines = 4;

    /// <summary>Lines a stair may miss between two that have it (a chipped tread, an ornament).</summary>
    public const int LineGap = 2;

    /// <summary>A stair that stops under a deck is carried up to it when the last gap is at most this many of its risers (ours; the expansion's medium platform stops about four risers short, the low one about eight).</summary>
    public const float MaxDeckGapRisers = 6f;

    /// <summary>Fewest cells deep a deck is (ours: a floor to stand on, not a parapet).</summary>
    public const int DeckCells = 8;

    /// <summary>A report aid: each chain found, as text (null: silent).</summary>
    [ThreadStatic] public static Action<string>? Trace;

    /// <summary>The stairs of a model (raw frame, Y up), the widest first, at most <paramref name="max"/>.</summary>
    public static List<AshfallRamp> Find(IReadOnlyList<Vector3> positions, IReadOnlyList<int> indices, Vector3 rawMin, Vector3 rawMax, int max = 12)
    {
        var size = rawMax - rawMin;
        float cell = MathF.Max(size.X, size.Z) / Resolution;
        if (cell <= 0f) return [];
        int nx = Math.Max(1, (int)MathF.Ceiling(size.X / cell)), nz = Math.Max(1, (int)MathF.Ceiling(size.Z / cell));
        var top = Heights(positions, indices, rawMin, cell, nx, nz);
        float flat = FlatCells * cell;
        var found = new List<(int Dir, int Line, int R0, int R1, float H0, float H1)>();
        for (int dir = 0; dir < 4; dir++)
        {
            bool alongX = dir < 2, forward = dir % 2 == 0;
            int lines = alongX ? nz : nx, len = alongX ? nx : nz;
            for (int line = 0; line < lines; line++)
            {
                float H(int i) { int k = forward ? i : len - 1 - i; return alongX ? top[k + nx * line] : top[line + nx * k]; }
                // plateaus: (first cell, last cell, height)
                var pl = new List<(int A, int B, float H)>();
                for (int i = 0; i < len; i++)
                {
                    float h = H(i);
                    if (float.IsNaN(h)) h = 0f;   // nothing of the model here: the ground it stands on
                    if (pl.Count > 0 && !float.IsNaN(pl[^1].H) && MathF.Abs(h - pl[^1].H) <= flat && pl[^1].B == i - 1) pl[^1] = (pl[^1].A, i, pl[^1].H);
                    else pl.Add((i, i, h));
                }
                for (int k = 0; k + MinRises < pl.Count;)
                {
                    // a chain from floor pl[k] rising through treads to a landing
                    if (float.IsNaN(pl[k].H) || pl[k].B - pl[k].A + 1 < MinTreadCells) { k++; continue; }
                    int m = k;
                    float rMin = float.MaxValue, rMax = 0f;
                    while (m + 1 < pl.Count)
                    {
                        var next = pl[m + 1];
                        if (float.IsNaN(next.H)) break;
                        float rise = next.H - pl[m].H;
                        if (rise <= flat) break;
                        float nMin = MathF.Min(rMin, rise), nMax = MathF.Max(rMax, rise);
                        if (nMax > 3f * nMin + flat) break;   // risers of one stair are alike (a chipped nosing may make one up to three times another)
                        if (m > k && pl[m].B - pl[m].A + 1 < MinTreadCells) break;   // every tread between floor and landing is a tread, not a slope's cell
                        rMin = nMin; rMax = nMax; m++;
                    }
                    if (m > k && pl[m].B - pl[m].A + 1 < MinTreadCells) m--;   // the landing is a place to stand too
                    int rises = m - k;
                    if (rises >= MinRises)
                    {
                        // treads between floor and landing; the landing pl[m] may be any length
                        float H0 = pl[k].H, H1 = pl[m].H;
                        int r0 = pl[k + 1].A, r1 = pl[m].A;   // cells where the first and the last rise start (the nosings)
                        // A stair that stops under a deck (the expansion's platforms: the last tread a riser or several below the deck's edge) is carried up to the deck when that last gap is at most
                        // MaxDeckGapRisers of its risers and the deck is a floor (at least DeckCells deep); a taller gap is a wall the stair ends in.
                        if (m + 1 < pl.Count && pl[m + 1].B - pl[m + 1].A + 1 >= DeckCells)
                        {
                            float gap = pl[m + 1].H - pl[m].H, mean = (H1 - H0) / rises;
                            if (gap > flat && gap <= MaxDeckGapRisers * mean) { H1 = pl[m + 1].H; r1 = pl[m + 1].A; m++; }
                        }
                        float run = (r1 - r0) * cell;
                        float slope = MathF.Atan2(H1 - H0, MathF.Max(run, 1e-6f)) * (180f / MathF.PI);
                        if (slope <= 75f && slope >= 10f) found.Add((dir, line, r0, r1, H0, H1));
                        Trace?.Invoke($"dir {dir} line {line}: cells {r0}..{r1} heights {H0:0.000}->{H1:0.000} rises {rises} slope {slope:0}");
                        k = m;
                    }
                    else k++;
                }
            }
        }
        // group equal chains on neighbouring lines
        var groups = new List<(int Dir, int L0, int L1, int R0, int R1, float H0, float H1)>();
        // (a line may miss its chain to a chip or an ornament: up to LineGap lines are bridged; the stair keeps the common span)
        foreach (var f in found.OrderBy(f => f.Dir).ThenBy(f => f.Line).ThenBy(f => f.R0).ThenBy(f => f.R1))
        {
            // lines belong together when they end on the same landing (a chipped step may start a line's chain higher up: the stair starts where its lowest line does)
            int gi = groups.FindLastIndex(g => g.Dir == f.Dir && f.Line > g.L1 && f.Line <= g.L1 + 1 + LineGap && Math.Abs(f.R1 - g.R1) <= 2 && MathF.Abs(f.H1 - g.H1) <= 3f * flat
                && f.R0 < g.R1 && g.R0 < f.R1);
            if (gi >= 0) { var g = groups[gi]; groups[gi] = (g.Dir, g.L0, f.Line, Math.Min(g.R0, f.R0), Math.Min(g.R1, f.R1), MathF.Min(g.H0, f.H0), MathF.Min(g.H1, f.H1)); }
            else groups.Add((f.Dir, f.Line, f.Line, f.R0, f.R1, f.H0, f.H1));
        }
        var result = new List<(int Area, AshfallRamp Ramp)>();
        foreach (var (dir, l0, l1, r0, r1, h0, h1) in groups)
        {
            if (l1 - l0 + 1 < MinLines || r1 <= r0) continue;
            bool alongX = dir < 2, forward = dir % 2 == 0;
            int len = alongX ? nx : nz;
            int c0 = forward ? r0 : len - r1, c1 = forward ? r1 : len - r0;   // cell edges along the axis, in grid order
            float a0 = c0 * cell, a1 = c1 * cell;
            float b0 = l0 * cell, b1 = (l1 + 1) * cell;
            Vector3 mn = alongX ? new(rawMin.X + a0, rawMin.Y + h0, rawMin.Z + b0) : new(rawMin.X + b0, rawMin.Y + h0, rawMin.Z + a0);
            Vector3 mx = alongX ? new(rawMin.X + a1, rawMin.Y + h1, rawMin.Z + b1) : new(rawMin.X + b1, rawMin.Y + h1, rawMin.Z + a1);
            mx = Vector3.Min(mx, rawMax); mn = Vector3.Max(mn, rawMin);
            result.Add(((l1 - l0 + 1) * (r1 - r0), new AshfallRamp(mn, mx, dir, rawMin.Y + h0, rawMin.Y + h1)));
        }
        return [.. result.OrderByDescending(r => r.Area).ThenBy(r => r.Ramp.Dir).ThenBy(r => r.Ramp.Min.X).ThenBy(r => r.Ramp.Min.Z).Take(max).Select(r => r.Ramp)];
    }

    /// <summary>The top heightfield the search reads (a report aid): cells along X and Z, the cell size, heights above the raw bottom (NaN where nothing is), row-major in X.</summary>
    public static (int Nx, int Nz, float Cell, float[] Top) TopHeights(IReadOnlyList<Vector3> positions, IReadOnlyList<int> indices, Vector3 rawMin, Vector3 rawMax)
    {
        var size = rawMax - rawMin;
        float cell = MathF.Max(size.X, size.Z) / Resolution;
        int nx = Math.Max(1, (int)MathF.Ceiling(size.X / cell)), nz = Math.Max(1, (int)MathF.Ceiling(size.Z / cell));
        return (nx, nz, cell, Heights(positions, indices, rawMin, cell, nx, nz));
    }

    /// <summary>The highest surface over each cell's centre (NaN where nothing is), heights above <paramref name="rawMin"/>.Y.</summary>
    static float[] Heights(IReadOnlyList<Vector3> p, IReadOnlyList<int> idx, Vector3 rawMin, float cell, int nx, int nz)
    {
        var top = new float[nx * nz];
        Array.Fill(top, float.NaN);
        for (int t = 0; t + 2 < idx.Count; t += 3)
        {
            Vector3 a = p[idx[t]] - rawMin, b = p[idx[t + 1]] - rawMin, c = p[idx[t + 2]] - rawMin;
            float x0 = MathF.Min(a.X, MathF.Min(b.X, c.X)), x1 = MathF.Max(a.X, MathF.Max(b.X, c.X));
            float z0 = MathF.Min(a.Z, MathF.Min(b.Z, c.Z)), z1 = MathF.Max(a.Z, MathF.Max(b.Z, c.Z));
            int i0 = Math.Max(0, (int)MathF.Ceiling(x0 / cell - 0.5f)), i1 = Math.Min(nx - 1, (int)MathF.Floor(x1 / cell - 0.5f));
            int k0 = Math.Max(0, (int)MathF.Ceiling(z0 / cell - 0.5f)), k1 = Math.Min(nz - 1, (int)MathF.Floor(z1 / cell - 0.5f));
            if (i0 > i1 || k0 > k1) continue;
            float det = (b.X - a.X) * (c.Z - a.Z) - (c.X - a.X) * (b.Z - a.Z);
            if (MathF.Abs(det) < 1e-12f) continue;   // a vertical face: no surface seen from above
            for (int k = k0; k <= k1; k++)
                for (int i = i0; i <= i1; i++)
                {
                    float px = (i + 0.5f) * cell, pz = (k + 0.5f) * cell;
                    float u = ((px - a.X) * (c.Z - a.Z) - (c.X - a.X) * (pz - a.Z)) / det;
                    float v = ((b.X - a.X) * (pz - a.Z) - (px - a.X) * (b.Z - a.Z)) / det;
                    if (u < -1e-5f || v < -1e-5f || u + v > 1f + 1e-5f) continue;
                    float y = a.Y + u * (b.Y - a.Y) + v * (c.Y - a.Y);
                    int q = i + nx * k;
                    if (float.IsNaN(top[q]) || y > top[q]) top[q] = y;
                }
        }
        return top;
    }
}
